import math


def dew_or_frost_point(x_gkg: float, p_pa: float) -> float:
    if x_gkg <= 0 or p_pa <= 0:
        raise ValueError("x_gkg and p_pa must be positive")

    x = x_gkg / 1000.0  # kg/kg
    e = x * p_pa / (0.622 + x)

    def enhancement(t: float) -> float:
        return 1.00062 + 3.14e-8 * p_pa + 5.6e-7 * t * t

    def es_water(t: float) -> float:
        return 611.2 * math.exp(17.62 * t / (243.12 + t))

    def es_ice(t: float) -> float:
        return 611.2 * math.exp(22.46 * t / (272.62 + t))

    def bisect(es_func, lo: float, hi: float) -> float:
        for _ in range(100):
            mid = (lo + hi) * 0.5
            if enhancement(mid) * es_func(mid) < e:
                lo = mid
            else:
                hi = mid
        return (lo + hi) * 0.5

    # Loese zuerst ueber Wasser
    t_water = bisect(es_water, -240.0, 100.0)

    if t_water < 0.0:
        # Frostpunkt: Loesung ueber Eis
        return bisect(es_ice, -240.0, 0.0)
    else:
        return t_water

import math


def evaluate_expr(s: str, variables: dict | None = None) -> float:
    if variables is None:
        variables = {}

    constants = {"pi": math.pi, "e": math.e}
    funcs = {
        "sin": math.sin,
        "cos": math.cos,
        "sqrt": math.sqrt,
        "exp": math.exp,
        "ln": math.log,
    }

    # --- Tokenizer ---
    tokens: list[tuple[str, object]] = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] in " \t":
            i += 1
            continue
        # Number (including scientific notation)
        if s[i].isdigit() or (s[i] == "." and i + 1 < n and s[i + 1].isdigit()):
            start = i
            while i < n and (s[i].isdigit() or s[i] == "."):
                i += 1
            if i < n and s[i] in "eE":
                i += 1
                if i < n and s[i] in "+-":
                    i += 1
                if i < n and s[i].isdigit():
                    while i < n and s[i].isdigit():
                        i += 1
            tokens.append(("number", float(s[start:i])))
        elif s[i].isalpha() or s[i] == "_":
            start = i
            while i < n and (s[i].isalnum() or s[i] == "_"):
                i += 1
            tokens.append(("ident", s[start:i]))
        elif s[i] in "+-*/^()":
            tokens.append(("op", s[i]))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {s[i]!r}")

    # --- Recursive-descent parser ---
    pos = 0

    def peek() -> tuple[str, object] | None:
        return tokens[pos] if pos < len(tokens) else None

    def parse_expr() -> float:
        """Addition / subtraction level."""
        result = parse_term()
        while pos < len(tokens) and tokens[pos][0] == "op" and tokens[pos][1] in ("+", "-"):
            op = tokens[pos][1]
            pos += 1
            right = parse_term()
            result = result + right if op == "+" else result - right
        return result

    def parse_term() -> float:
        """Multiplication / division level."""
        result = parse_unary()
        while pos < len(tokens) and tokens[pos][0] == "op" and tokens[pos][1] in ("*", "/"):
            op = tokens[pos][1]
            pos += 1
            right = parse_unary()
            if op == "*":
                result *= right
            else:
                if right == 0:
                    raise ValueError("Division by zero")
                result /= right
        return result

    def parse_unary() -> float:
        """Unary + / - (binds weaker than ^)."""
        if pos < len(tokens) and tokens[pos][0] == "op" and tokens[pos][1] in ("+", "-"):
            op = tokens[pos][1]
            pos += 1
            operand = parse_unary()
            return -operand if op == "-" else operand
        return parse_power()

    def parse_power() -> float:
        """Power ^ (right-associative, binds tighter than unary +/-)."""
        result = parse_atom()
        while pos < len(tokens) and tokens[pos][0] == "op" and tokens[pos][1] == "^":
            pos += 1
            exponent = parse_unary()
            result = result ** exponent
        return result

    def parse_atom() -> float:
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")

        tok = tokens[pos]

        # Parenthesized expression
        if tok[0] == "op" and tok[1] == "(":
            pos += 1
            result = parse_expr()
            if pos >= len(tokens) or tokens[pos] != ("op", ")"):
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return result

        # Function call: name followed by '('
        if tok[0] == "ident" and tok[1] in funcs:
            if pos + 1 < len(tokens) and tokens[pos + 1] == ("op", "("):
                pos += 2  # skip function name and '('
                arg = parse_expr()
                if pos >= len(tokens) or tokens[pos] != ("op", ")"):
                    raise ValueError("Missing closing parenthesis")
                pos += 1
                try:
                    return funcs[tok[1]](arg)
                except (ValueError, math domain error):
                    raise ValueError(f"Domain error in {tok[1]}({arg})")

        # Plain identifier → constant or variable
        if tok[0] == "ident":
            name = tok[1]
            pos += 1
            if name in constants:
                return constants[name]
            if name in variables:
                return float(variables[name])
            raise ValueError(f"Unknown name: {name!r}")

        # Number literal
        if tok[0] == "number":
            pos += 1
            return tok[1]

        raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

def rx_fullmatch(pattern: str, text: str) -> bool:
    """
    Thompson-NFA-basiertes Full-Match mit polynomialer Laufzeit.
    Unterstuetzt: Literale, '.', *, +, ?, ( ), |, [abc], [a-z0-9], [^...], \\-Escapes.
    Ungueltige Muster -> ValueError.
    """

    class NFAState:
        __slots__ = ['kind', 'pred', 'next']

        def __init__(self, kind='epsilon', pred=None):
            self.kind = kind   # 'epsilon' or 'consume'
            self.pred = pred   # callable(c) -> bool for consume states
            self.next = []

    class Fragment:
        __slots__ = ['start', 'end']

        def __init__(self, start, end):
            self.start = start
            self.end = end

    # ---------- Parser ----------
    pos = [0]
    s = pattern

    def peek():
        if pos[0] < len(s):
            return s[pos[0]]
        return None

    def advance():
        ch = s[pos[0]]
        pos[0] += 1
        return ch

    def parse_regex():
        frag = parse_concat()
        while peek() == '|':
            advance()
            frag2 = parse_concat()
            start = NFAState('epsilon')
            end = NFAState('epsilon')
            start.next.append(frag.start)
            start.next.append(frag2.start)
            frag.end.next.append(end)
            frag2.end.next.append(end)
            frag = Fragment(start, end)
        return frag

    def parse_concat():
        parts = []
        while pos[0] < len(s) and peek() not in ('|', ')'):
            parts.append(parse_quantified())
        if not parts:
            start = NFAState('epsilon')
            end = NFAState('epsilon')
            start.next.append(end)
            return Fragment(start, end)
        result = parts[0]
        for p in parts[1:]:
            result.end.next.append(p.start)
            result = Fragment(result.start, p.end)
        return result

    def parse_quantified():
        frag = parse_atom()
        while pos[0] < len(s) and peek() in ('*', '+', '?'):
            op = advance()
            if op == '*':
                start = NFAState('epsilon')
                end = NFAState('epsilon')
                start.next.append(frag.start)
                start.next.append(end)
                frag.end.next.append(frag.start)
                frag.end.next.append(end)
                frag = Fragment(start, end)
            elif op == '+':
                start = NFAState('epsilon')
                end = NFAState('epsilon')
                start.next.append(frag.start)
                frag.end.next.append(frag.start)
                frag.end.next.append(end)
                frag = Fragment(start, end)
            else:  # '?'
                start = NFAState('epsilon')
                end = NFAState('epsilon')
                start.next.append(frag.start)
                start.next.append(end)
                frag.end.next.append(end)
                frag = Fragment(start, end)
        return frag

    def parse_atom():
        if pos[0] >= len(s):
            raise ValueError("Unexpected end of pattern")
        ch = peek()
        if ch in ('*', '+', '?'):
            raise ValueError("Quantifier without operand")

        if ch == '(':
            advance()
            frag = parse_regex()
            if pos[0] >= len(s) or peek() != ')':
                raise ValueError("Missing closing parenthesis")
            advance()
            return frag

        elif ch == '[':
            advance()
            negated = False
            if pos[0] < len(s) and peek() == '^':
                negated = True
                advance()
            chars = []
            while pos[0] < len(s) and peek() != ']':
                if peek() == '\\':
                    advance()
                    if pos[0] >= len(s):
                        raise ValueError("Unexpected end after backslash")
                    chars.append(advance())
                else:
                    c = advance()
                    if (pos[0] < len(s) and peek() == '-'
                            and pos[0] + 1 < len(s) and s[pos[0] + 1] != ']'):
                        advance()  # consume '-'
                        end_char = advance()
                        for code in range(ord(c), ord(end_char) + 1):
                            chars.append(chr(code))
                    else:
                        chars.append(c)
            if pos[0] >= len(s) or peek() != ']':
                raise ValueError("Missing closing bracket")
            advance()  # consume ']'
            char_set = frozenset(chars)
            if negated:
                pred = lambda c: c not in char_set
            else:
                pred = lambda c: c in char_set
            state = NFAState('consume', pred=pred)
            end = NFAState('epsilon')
            state.next.append(end)
            return Fragment(state, end)

        elif ch == '.':
            advance()
            state = NFAState('consume', pred=lambda c: True)
            end = NFAState('epsilon')
            state.next.append(end)
            return Fragment(state, end)

        elif ch == '\\':
            advance()
            if pos[0] >= len(s):
                raise ValueError("Unexpected end after backslash")
            literal = advance()
            state = NFAState('consume', pred=lambda c, lit=literal: c == lit)
            end = NFAState('epsilon')
            state.next.append(end)
            return Fragment(state, end)

        else:
            advance()
            state = NFAState('consume', pred=lambda c, ch=ch: c == ch)
            end = NFAState('epsilon')
            state.next.append(end)
            return Fragment(state, end)

    # ---------- Build NFA ----------
    frag = parse_regex()
    if pos[0] < len(s):
        raise ValueError("Unexpected characters in pattern")

    # ---------- Simulate NFA ----------
    def epsilon_closure(states):
        result = set(states)
        stack = list(states)
        while stack:
            st = stack.pop()
            if st.kind == 'epsilon':
                for nxt in st.next:
                    if nxt not in result:
                        result.add(nxt)
                        stack.append(nxt)
        return result

    accept = frag.end
    active = epsilon_closure({frag.start})

    for ch in text:
        next_active = set()
        for st in active:
            if st.kind == 'consume' and st.pred(ch):
                next_active.update(st.next)
        active = epsilon_closure(next_active)

    return accept in active

import heapq


def k_shortest_paths(graph: dict, src, dst, k: int) -> list[tuple[float, list]]:
    if src == dst:
        return [(0, [src])]

    def dijkstra(start, target, excluded_edges, excluded_nodes):
        dist = {start: 0}
        prev = {}
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist.get(u, float('inf')):
                continue
            if u == target:
                path = [u]
                while u != start:
                    u = prev[u]
                    path.append(u)
                path.reverse()
                return d, path
            if u in excluded_nodes:
                continue
            for v, w in graph.get(u, {}).items():
                if (u, v) in excluded_edges:
                    continue
                if v in excluded_nodes:
                    continue
                nd = d + w
                if nd < dist.get(v, float('inf')):
                    dist[v] = nd
                    prev[v] = u
                    heapq.heappush(heap, (nd, v))
        return None, None

    cost0, path0 = dijkstra(src, dst, set(), set())
    if cost0 is None:
        return []

    result = [(cost0, path0)]
    candidates = []
    found = {tuple(path0)}
    counter = 0

    for i in range(1, k):
        prev_path = result[i - 1][1]

        for spur_idx in range(len(prev_path) - 1):
            spur_node = prev_path[spur_idx]
            root_path = prev_path[:spur_idx + 1]

            root_cost = 0
            for j in range(spur_idx):
                root_cost += graph.get(prev_path[j], {}).get(prev_path[j + 1], 0)

            excluded_edges = set()
            for _, p in result:
                if p[:spur_idx + 1] == root_path:
                    excluded_edges.add((spur_node, p[spur_idx + 1]))

            excluded_nodes = set(root_path[:-1])

            spur_cost, spur_path = dijkstra(spur_node, dst, excluded_edges, excluded_nodes)
            if spur_path is None:
                continue

            full_path = root_path + spur_path[1:]
            total_cost = root_cost + spur_cost

            if tuple(full_path) not in found:
                found.add(tuple(full_path))
                heapq.heappush(candidates, (total_cost, counter, full_path))
                counter += 1

        if not candidates:
            break

        best_cost, _, best_path = heapq.heappop(candidates)
        result.append((best_cost, best_path))

    return result

import math


def fit_exp_decay(t: list[float], y: list[float]) -> tuple[float, float, float]:
    """Fit y = A * exp(-t / tau) + C via Levenberg-Marquardt (pure stdlib)."""
    if len(t) < 3:
        raise ValueError("At least 3 data points required")
    if len(y) < 3:
        raise ValueError("At least 3 data points required")

    n = min(len(t), len(y))
    t = t[:n]
    y = y[:n]

    # --- Initial parameter estimates ---
    tail_len = max(1, n // 3)
    tail = y[-tail_len:]
    C = sum(tail) / tail_len

    A = y[0] - C  # amplitude (can be negative for rising curve)

    tau = _estimate_tau(t, y, C, A)
    tau = max(tau, 1e-9)

    # --- Levenberg-Marquardt iteration ---
    lam = 1e-2
    max_iter = 300
    eps = 1e-14

    def residual(i: int, a: float, tau_: float, c: float) -> float:
        return y[i] - (a * math.exp(-t[i] / tau_) + c)

    def jac_row(i: int, a: float, tau_: float, c: float) -> tuple[float, float, float]:
        e = math.exp(-t[i] / tau_)
        return (e, a * t[i] / (tau_ * tau_) * e, 1.0)

    def cost(a: float, tau_: float, c: float) -> float:
        s = 0.0
        for i in range(n):
            r = residual(i, a, tau_, c)
            s += r * r
        return s

    cur_cost = cost(A, tau, C)

    for _ in range(max_iter):
        # Compute J^T J (3×3) and J^T r (3)
        JTJ = [[0.0] * 3 for _ in range(3)]
        JTr = [0.0, 0.0, 0.0]
        for i in range(n):
            r = residual(i, A, tau, C)
            j = jac_row(i, A, tau, C)
            JTr[0] += j[0] * r
            JTr[1] += j[1] * r
            JTr[2] += j[2] * r
            JTJ[0][0] += j[0] * j[0]
            JTJ[0][1] += j[0] * j[1]
            JTJ[0][2] += j[0] * j[2]
            JTJ[1][0] += j[1] * j[0]
            JTJ[1][1] += j[1] * j[1]
            JTJ[1][2] += j[1] * j[2]
            JTJ[2][0] += j[2] * j[0]
            JTJ[2][1] += j[2] * j[1]
            JTJ[2][2] += j[2] * j[2]

        # Symmetrise (it's already symmetric, but be safe)
        for i in range(3):
            for j in range(i + 1, 3):
                avg = (JTJ[i][j] + JTJ[j][i]) * 0.5
                JTJ[i][j] = avg
                JTJ[j][i] = avg

        # Marquardt diagonal scaling
        for i in range(3):
            JTJ[i][i] += lam * (JTJ[i][i] + eps)

        # Solve 3×3 system: M * delta = -JTr
        rhs = [-JTr[0], -JTr[1], -JTr[2]]
        delta = _solve3(JTJ, rhs)

        if delta is None:
            lam *= 10.0
            continue

        new_A = A + delta[0]
        new_tau = tau + delta[1]
        new_C = C + delta[2]

        # Enforce tau > 0
        if new_tau <= 0.0:
            lam *= 10.0
            continue

        new_cost = cost(new_A, new_tau, new_C)

        if new_cost < cur_cost:
            A, tau, C = new_A, new_tau, new_C
            cur_cost = new_cost
            lam *= 0.5
            if lam < 1e-14:
                break
            # Convergence check
            if abs(delta[0]) < 1e-12 * abs(A) + 1e-14 and \
               abs(delta[1]) < 1e-12 * abs(tau) + 1e-14 and \
               abs(delta[2]) < 1e-12 * abs(C) + 1e-14:
                break
        else:
            lam *= 10.0
            if lam > 1e12:
                break

    return (A, tau, C)


def _estimate_tau(t: list[float], y: list[float], C: float, A: float) -> float:
    """Estimate tau from the 63.2% crossing point."""
    if abs(A) < 1e-15:
        return max(1.0, (t[-1] - t[0]) / 4.0)

    target_ratio = 0.632  # 1 - 1/e
    target_val = C + A * target_ratio

    # Find the data point whose y value is closest to target_val
    best_tau = max(1e-6, (t[-1] - t[0]) / 4.0)
    best_dist = float('inf')

    for i in range(n):
        dist = abs(y[i] - target_val)
        if dist < best_dist:
            best_dist = dist
            # Linear interpolation between adjacent points for better estimate
            if i < n - 1:
                if y[i] != y[i + 1]:
                    frac = (target_val - y[i]) / (y[i + 1] - y[i])
                    t_cross = t[i] + frac * (t[i + 1] - t[i])
                else:
                    t_cross = t[i]
            elif i > 0:
                if y[i] != y[i - 1]:
                    frac = (target_val - y[i]) / (y[i - 1] - y[i])
                    t_cross = t[i] + frac * (t[i - 1] - t[i])
                else:
                    t_cross = t[i]
            else:
                t_cross = t[i]
            if t_cross > 0:
                best_tau = t_cross

    # Fallback: if best_tau is unrealistically small/large, use a simple heuristic
    span = t[-1] - t[0] if len(t) > 1 else 1.0
    if span <= 0:
        return 1.0
    if best_tau < 1e-6:
        best_tau = span / 4.0
    if best_tau > span * 2.0:
        best_tau = span / 2.0

    return best_tau


def _solve3(M: list[list[float]], rhs: list[float]) -> list[float] | None:
    """Solve a 3×3 linear system via Gaussian elimination with partial pivoting."""
    # Build augmented matrix
    aug = [[M[i][j] for j in range(3)] + [rhs[i]] for i in range(3)]

    # Forward elimination
    for col in range(3):
        # Partial pivoting
        max_row = col
        max_val = abs(aug[col][col])
        for row in range(col + 1, 3):
            if abs(aug[row][col]) > max_val:
                max_val = abs(aug[row][col])
                max_row = row
        if max_val < 1e-30:
            return None
        if max_row != col:
            aug[col], aug[max_row] = aug[max_row], aug[col]

        pivot = aug[col][col]
        for row in range(col + 1, 3):
            factor = aug[row][col] / pivot
            for k in range(col, 4):
                aug[row][k] -= factor * aug[col][k]

    # Back substitution
    x = [0.0] * 3
    for row in range(2, -1, -1):
        if abs(aug[row][row]) < 1e-30:
            return None
        x[row] = aug[row][3]
        for col in range(row + 1, 3):
            x[row] -= aug[row][col] * x[col]
        x[row] /= aug[row][row]

    return x


# Module-level helper variable used inside _estimate_tau
# (set via closure-free approach – _estimate_tau references n from enclosing scope
#  by receiving it implicitly; we fix this by passing n explicitly.)
# To keep _estimate_tau self-contained, we redefine with explicit n:

def _estimate_tau(t: list[float], y: list[float], C: float, A: float) -> float:
    """Estimate tau from the 63.2% crossing point."""
    if abs(A) < 1e-15:
        span = t[-1] - t[0] if len(t) > 1 else 1.0
        return max(1e-6, span / 4.0)

    n = len(t)
    target_ratio = 0.632
    target_val = C + A * target_ratio

    best_tau = max(1e-6, (t[-1] - t[0]) / 4.0)
    best_dist = float('inf')

    for i in range(n):
        dist = abs(y[i] - target_val)
        if dist < best_dist:
            best_dist = dist
            if i < n - 1 and abs(y[i + 1] - y[i]) > 1e-30:
                frac = (target_val - y[i]) / (y[i + 1] - y[i])
                t_cross = t[i] + frac * (t[i + 1] - t[i])
            elif i > 0 and abs(y[i - 1] - y[i]) > 1e-30:
                frac = (target_val - y[i]) / (y[i - 1] - y[i])
                t_cross = t[i] + frac * (t[i - 1] - t[i])
            else:
                t_cross = t[i]
            if t_cross > 0:
                best_tau = t_cross

    span = t[-1] - t[0] if len(t) > 1 else 1.0
    if span <= 0:
        return 1.0
    if best_tau < 1e-6:
        best_tau = span / 4.0
    if best_tau > span * 2.0:
        best_tau = span / 2.0

    return best_tau

def crc_generic(data: bytes, width: int, poly: int, init: int, refin: bool, refout: bool, xorout: int) -> int:
    if isinstance(width, bool) or not isinstance(width, int):
        raise ValueError("width must be an integer between 1 and 64")
    if width < 1 or width > 64:
        raise ValueError("width must be between 1 and 64")

    mask = (1 << width) - 1

    def _reflect(value: int, bits: int) -> int:
        result = 0
        for i in range(bits):
            if value & (1 << i):
                result |= 1 << (bits - 1 - i)
        return result

    crc = init & mask

    for byte in data:
        if refin:
            byte = _reflect(byte, 8)
        for i in range(8):
            top = (crc >> (width - 1)) & 1
            bit = (byte >> (7 - i)) & 1
            if top ^ bit:
                crc = ((crc << 1) ^ poly) & mask
            else:
                crc = (crc << 1) & mask

    if refout:
        crc = _reflect(crc, width)

    return (crc ^ xorout) & mask
